"use client";
import React, { useState } from "react";
import type { ConsultationAction, ConsultationCommand, ConsultationSession, FinancialBasis } from "@/lib/consultation/contracts";
import { formatJalali, toPersianDigits } from "@/lib/format";
import Field from "./Field";
import { SessionReplies } from "./RepliesPanel";
import type { ReplyCommand, ReplyRead } from "@/lib/consultation/replies";
import ActionFeedback from "./ActionFeedback";
const labels = { draft: "پیش‌نویس", submitted: "در انتظار تأیید آرش", approved: "تأییدشده؛ هنوز منتشر نشده", published: "منتشرشده برای عضو", withdrawn: "پس‌گرفته‌شده" };
const feedbackLabels = { viewed: "مشاهده‌شده", acknowledged: "دریافت توسط عضو تأیید شد", doing: "در حال انجام", done: "انجام‌شده طبق اعلام", question: "پرسش", partial: "بخشی انجام‌شده طبق اعلام", not_done: "انجام‌نشده طبق اعلام" };
export function sameBasis(left: FinancialBasis, right: FinancialBasis) { return left.holdingsVersionId === right.holdingsVersionId && left.cashFlowVersionId === right.cashFlowVersionId && left.goalsVersionId === right.goalsVersionId && left.cashFlowPeriod.startOn === right.cashFlowPeriod.startOn && left.cashFlowPeriod.endOn === right.cashFlowPeriod.endOn; }
export default function SessionCard({ session, latest, advisor, owner, revoked, basis, feedback, privateNote, locked, onCommand, onEdit, onDirty, replies, onReply, onReplyDirty, onCancelReply, replyLocked, replyError, onReloadReplies, repliesReloadLocked, activeFeedbackKey, feedbackLocked, onFeedbackBegin, onFeedbackCancel, extendedFeedbackWrite = false }: {
  session: ConsultationSession; latest: boolean; advisor: boolean; owner: boolean; revoked: boolean; basis: FinancialBasis; feedback: ConsultationAction[]; privateNote?: string | null; locked: boolean;
  onCommand: (command: ConsultationCommand) => Promise<boolean>; onEdit: () => void; onDirty: () => void;
  replyError?: string; onReloadReplies?: () => void; repliesReloadLocked?: boolean; replyLocked?: boolean; replies?: ReplyRead; onReply?: (command: ReplyCommand) => Promise<boolean>; onReplyDirty?: () => void; onCancelReply?: () => void;
  activeFeedbackKey?: string | null; feedbackLocked?: boolean; onFeedbackBegin?: (key: string) => void; onFeedbackCancel?: () => void;
  extendedFeedbackWrite?: boolean;
}) {
  const [question, setQuestion] = useState("");
  const today = new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Tehran", year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date());
  const expired = session.body.reviewOn < today;
  const stale = !sameBasis(session.body.basis, basis), published = session.state === "published";
  const transition = (kind: "submit" | "approve" | "publish" | "withdraw") => onCommand({ kind, relationshipId: session.relationshipId, sessionId: session.id, contentHash: session.contentHash, note: null });
  const report = (status: "viewed" | "acknowledged" | "doing" | "done" | "question", actionKey: string | null = null) => onCommand({ kind: "feedback", relationshipId: session.relationshipId, sessionId: session.id, actionKey, baseVersion: Math.max(0, ...feedback.filter(item => item.actionKey === actionKey).map(item => item.version)), status, text: status === "question" ? question.trim() : null });
  return <article className="card min-w-0 space-y-4 p-4 sm:p-5" aria-label={`جمع‌بندی نسخهٔ ${toPersianDigits(session.version)}`}>
    <header className="space-y-2"><h3 className="break-words text-lg font-bold">{session.body.topic}</h3><p className="text-sm">نسخهٔ {toPersianDigits(session.version)} · {labels[session.state]} · ثبت {formatJalali(session.createdAt)}</p>{!latest && <p className="text-sm">نسخهٔ تاریخی؛ نسخهٔ تازه‌تری از این جمع‌بندی وجود دارد.</p>}</header>
    {session.approval && <p className="text-sm">تأیید آرش برای همین نسخه در {formatJalali(session.approval.createdAt)} ثبت شده است؛ تأیید، انتشار خودکار نیست.</p>}
    {expired && <p role="status" className="text-sm">موعد بازبینی این نسخه گذشته است؛ برای تأیید یا انتشار، نسخهٔ تازه بررسی شود.</p>}
    {stale && <p className="text-sm leading-7" role="status">پروندهٔ فعلی با مبنای این نسخه یکسان نیست. پیش از تأیید یا انتشار، نسخهٔ تازه با اطلاعات فعلی بررسی شود؛ تغییر دورهٔ نمایشی نیز ممکن است علت تفاوت باشد.</p>}
    <dl className="space-y-3 text-sm leading-7">{[["هدف", session.body.goal], ["جمع‌بندی", session.body.clientSummary], ["دلیل و تناسب", session.body.rationale], ["محدودیت‌ها", session.body.limitations]].map(([label, text]) => <div key={label}><dt className="font-bold">{label}</dt><dd className="whitespace-pre-wrap break-words">{text}</dd></div>)}<div><dt className="font-bold">موعد بازبینی</dt><dd><time dateTime={session.body.reviewOn}>{formatJalali(session.body.reviewOn)}</time></dd></div></dl>
    <details className="text-sm leading-7"><summary className="cursor-pointer font-bold">شاهدها و مبنای این نسخه</summary><p>دورهٔ مبنا: {toPersianDigits(session.body.basis.cashFlowPeriod.startOn)} تا {toPersianDigits(session.body.basis.cashFlowPeriod.endOn)}</p><p>دارایی: {session.body.basis.holdingsVersionId ? "نسخهٔ مشخص پیوند دارد" : "نسخه‌ای در مبنا نبود"}؛ جریان نقد: {session.body.basis.cashFlowVersionId ? "نسخهٔ مشخص پیوند دارد" : "نسخه‌ای در مبنا نبود"}؛ هدف‌ها: {session.body.basis.goalsVersionId ? "نسخهٔ مشخص پیوند دارد" : "نسخه‌ای در مبنا نبود"}.</p><ul className="space-y-2">{session.body.evidence.map((item, index) => <li key={index} className="break-words">{item.label} · {formatJalali(item.asOf)} {item.url && <a href={item.url} target="_blank" rel="noopener noreferrer" className="underline">بازکردن منبع</a>}</li>)}</ul><p>{toPersianDigits(session.body.researchVersionIds.length)} نسخهٔ پژوهش پیوندخورده؛ تأیید داخلی پژوهش با تأیید این جمع‌بندی یکی نیست.</p></details>
    {advisor && privateNote && <details className="rounded-lg border border-line p-3 text-sm"><summary>یادداشت خصوصی مشاور</summary><p className="whitespace-pre-wrap break-words leading-7">{privateNote}</p></details>}
    {advisor && !revoked && <div className="flex flex-wrap gap-3"><button className="btn !whitespace-normal max-w-full min-w-0 break-words btn-outline" disabled={locked || !latest} onClick={onEdit}>اصلاح در نسخهٔ تازه</button>{latest && session.state === "draft" && <button className="btn !whitespace-normal max-w-full min-w-0 break-words btn-outline" disabled={locked || stale || expired} onClick={() => void transition("submit")}>ارسال همین نسخه برای تأیید</button>}{owner && latest && session.state === "submitted" && <button className="btn !whitespace-normal max-w-full min-w-0 break-words btn-gold" disabled={locked || stale || expired} onClick={() => void transition("approve")}>تأیید آرش برای همین نسخه</button>}{latest && session.state === "approved" && <button className="btn !whitespace-normal max-w-full min-w-0 break-words btn-gold" disabled={locked || stale || expired} onClick={() => void transition("publish")}>انتشار همین نسخه برای عضو</button>}{["submitted", "approved", "published"].includes(session.state) && <button className="btn !whitespace-normal max-w-full min-w-0 break-words btn-outline" disabled={locked} onClick={() => void transition("withdraw")}>پس‌گرفتن این نسخه</button>}</div>}
    <section className="space-y-3"><h4 className="font-bold">اقدام‌های توافق‌شده</h4>{session.body.actions.length === 0 && <p className="text-sm">اقدامی در این نسخه ثبت نشده است.</p>}{session.body.actions.map(action => {
      const editorKey = `${session.id}:${action.actionKey}`;
      const canReport = published && !revoked && (action.responsible === "advisor" ? advisor : !advisor);
      return <div key={action.actionKey} className="space-y-2 rounded-lg border border-line p-3 text-sm"><p className="break-words font-bold">{action.title}</p><p>مسئول: {action.responsible === "member" ? "عضو" : "مشاور"} · موعد: {formatJalali(action.dueOn)}</p>{canReport && <>
        <div className="flex flex-wrap gap-2"><button className="btn !whitespace-normal max-w-full min-w-0 break-words btn-outline" disabled={locked} onClick={() => void report("doing", action.actionKey)}>اعلام شروع اقدام</button><button className="btn !whitespace-normal max-w-full min-w-0 break-words btn-outline" disabled={locked} onClick={() => void report("done", action.actionKey)}>اعلام انجام اقدام</button></div>
        {(extendedFeedbackWrite || activeFeedbackKey === editorKey) && <ActionFeedback writeEnabled={extendedFeedbackWrite} baseVersion={Math.max(0, ...feedback.filter(item => item.actionKey === action.actionKey).map(item => item.version))} locked={(feedbackLocked ?? locked) || Boolean(activeFeedbackKey && activeFeedbackKey !== editorKey)} onBegin={() => onFeedbackBegin ? onFeedbackBegin(editorKey) : onDirty()} onCancel={() => onFeedbackCancel?.()} onSave={edit => onCommand({ kind: "feedback", relationshipId: session.relationshipId, sessionId: session.id, actionKey: action.actionKey, baseVersion: edit.baseVersion, status: edit.status, text: edit.text })} />}
      </>}</div>;
    })}</section>
    {!advisor && published && !revoked && <fieldset disabled={locked} className="space-y-3"><legend className="font-bold">مشاهده و اعلام عضو</legend><p className="text-xs leading-6">ثبت مشاهده، دریافت یا انجام اقدام، اعلام شماست؛ به معنی تأیید معامله نزد کارگزاری نیست.</p><div className="flex flex-wrap gap-2"><button className="btn !whitespace-normal max-w-full min-w-0 break-words btn-outline" onClick={() => void report("viewed")}>این نسخه را مشاهده کردم</button><button className="btn !whitespace-normal max-w-full min-w-0 break-words btn-outline" onClick={() => void report("acknowledged")}>دریافت این نسخه را تأیید می‌کنم</button></div><Field label="پرسش دربارهٔ همین نسخه" multiline maxLength={2000} value={question} onChange={value => { setQuestion(value); onDirty(); }} /><button className="btn !whitespace-normal max-w-full min-w-0 break-words btn-outline" disabled={!question.trim()} onClick={() => void report("question")}>ثبت پرسش خصوصی</button></fieldset>}
    <details className="text-sm"><summary className="cursor-pointer font-bold">سابقهٔ مشاهده و اقدام‌ها ({toPersianDigits(feedback.length)})</summary>{feedback.length === 0 ? <p className="mt-2">رویدادی ثبت نشده است.</p> : <ul className="mt-3 space-y-3">{feedback.map(item => <li key={item.id} className="min-w-0 space-y-1 border-b border-line pb-2"><p>{feedbackLabels[item.status]} · <time dateTime={item.createdAt}>{formatJalali(item.createdAt)}</time> · ثبت شمارهٔ {toPersianDigits(item.version)}</p>{item.actionKey && <p className="break-words">اقدام مربوط: {session.body.actions.find(action => action.actionKey === item.actionKey)?.title ?? "عنوان اقدام در این نسخه در دسترس نیست"}</p>}{item.text && <p className="whitespace-pre-wrap break-words leading-7">{item.text}</p>}</li>)}</ul>}</details>
    {replyError && <section className="space-y-2"><p role="alert" className="text-sm leading-7">{replyError}</p><button type="button" className="btn btn-outline !whitespace-normal max-w-full min-w-0 break-words" disabled={repliesReloadLocked || locked} onClick={onReloadReplies}>دوباره خواندن پاسخ‌ها</button></section>}
    {replies && !replyError && <SessionReplies data={replies} feedback={feedback} sessionVersion={session.version} sessionActions={session.body.actions} advisor={advisor} locked={replyLocked ?? locked} onCommand={onReply} onDirty={onReplyDirty ?? onDirty} onCancel={onCancelReply} />}
  </article>;
}

// Persian / Iranian financial formatting — pure, dependency-free, deterministic.
// Safe to import in both server and client components. Money is handled as
// integer Toman. Dates use the Persian (Jalali) calendar via Intl so the output
// is the same on server and client (no hydration mismatch).

const FA_DIGITS = ["۰", "۱", "۲", "۳", "۴", "۵", "۶", "۷", "۸", "۹"];

/** Convert all Latin digits in a string/number to Persian digits. */
export function toPersianDigits(input: string | number): string {
  return String(input).replace(/\d/g, (d) => FA_DIGITS[Number(d)]);
}

const FA_AR_DIGITS = /[۰-۹٠-٩]/g;
const TO_LATIN: Record<string, string> = {
  "۰": "0", "۱": "1", "۲": "2", "۳": "3", "۴": "4", "۵": "5", "۶": "6", "۷": "7", "۸": "8", "۹": "9",
  "٠": "0", "١": "1", "٢": "2", "٣": "3", "٤": "4", "٥": "5", "٦": "6", "٧": "7", "٨": "8", "٩": "9",
};

/** Convert Persian/Arabic digits to Latin — use before parsing or validating user input. */
export function toLatinDigits(input: string): string {
  return input.replace(FA_AR_DIGITS, (d) => TO_LATIN[d] ?? d);
}

function groupThousands(n: number): string {
  return Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, "٬");
}

/** Full Toman amount, e.g. 1250000 → "۱٬۲۵۰٬۰۰۰ تومان". */
export function formatToman(value: number): string {
  return `${toPersianDigits(groupThousands(value))} تومان`;
}

/**
 * Abbreviated Toman, e.g. 3_500_000_000 → "۳٫۵ میلیارد تومان".
 *
 * ── چرا پلهٔ «همت» اضافه شد ───────────────────────────────────────────────
 * بالاترین پلهٔ قبلی «میلیارد» بود، پس جمع‌های سطحِ بازار — ارزشِ معاملاتِ کل و
 * خالصِ پولِ حقیقی — به شکلِ «۳۳۲٬۹۲۸٬۱۴۶٫۲ میلیارد تومان» درمی‌آمدند: عددی که
 * نه خوانده می‌شود، نه در کارتِ سنجه جا می‌شود. «همت» (هزار میلیارد تومان)
 * واحدِ متعارفِ همین بازار است و در `TodayDashboard` هم به‌صورتِ محلی ساخته
 * شده بود؛ حالا یک بار اینجاست و همه از همین می‌خوانند.
 */
export function formatTomanShort(value: number): string {
  const abs = Math.abs(value);
  let num = value;
  let unit = "";
  if (abs >= 1_000_000_000_000) {
    num = value / 1_000_000_000_000;
    unit = " همت";
  } else if (abs >= 1_000_000_000) {
    num = value / 1_000_000_000;
    unit = " میلیارد";
  } else if (abs >= 1_000_000) {
    num = value / 1_000_000;
    unit = " میلیون";
  } else if (abs >= 1_000) {
    num = value / 1_000;
    unit = " هزار";
  }
  // علامتِ منفی: همان «−» (U+2212) که `formatPercent` می‌گذارد، نه خطِ تیرهٔ
  // اسکی. دو علامتِ متفاوت برای یک معنا در یک صفحه، و در RTL خطِ تیرهٔ اسکی
  // کنارِ رقمِ فارسی جهتش مبهم می‌شود.
  const sign = num < 0 ? "−" : "";
  const mag = Math.abs(num);
  const body = unit ? mag.toFixed(mag % 1 === 0 ? 0 : 1) : groupThousands(mag);
  // «همت» خودش مخفّفِ «هزار میلیارد تومان» است، پس «۴۱۵٫۴ همت تومان» یعنی
  // «…تومان تومان». واحد یک بار نوشته می‌شود؛ بقیهٔ پله‌ها («میلیارد»،
  // «میلیون»، …) عدد خالص‌اند و «تومان» را لازم دارند.
  const currency = unit === " همت" ? "" : " تومان";
  return `${sign}${toPersianDigits(body).replace(".", "٫")}${unit}${currency}`;
}

/** Percent with Persian decimal/sign, e.g. 12.5 → "٪۱۲٫۵", -3.2 → "−٪۳٫۲". */
export function formatPercent(value: number, digits = 1): string {
  const sign = value < 0 ? "−" : "";
  const body = toPersianDigits(Math.abs(value).toFixed(digits)).replace(".", "٫");
  return `${sign}٪${body}`;
}

/** Signed change with arrow, e.g. 2.4 → "▲ ٪۲٫۴". */
export function formatSignedPercent(value: number, digits = 1): string {
  const arrow = value > 0 ? "▲" : value < 0 ? "▼" : "•";
  return `${arrow} ${formatPercent(Math.abs(value), digits)}`;
}

/** Screen-reader phrasing for a delta, e.g. "افزایش ۲٫۴ درصدی". */
export function describeDelta(value: number): string {
  if (value > 0) return `افزایش ${toPersianDigits(Math.abs(value).toFixed(1))} درصدی`;
  if (value < 0) return `کاهش ${toPersianDigits(Math.abs(value).toFixed(1))} درصدی`;
  return "بدون تغییر";
}

/** Dollar price with Persian digits, e.g. 67250.3 → "۶۷٬۲۵۰ دلار"; sub-1 keeps 3 significant digits. */
export function formatUsd(value: number): string {
  const s = value >= 1 ? Math.round(value).toLocaleString("en-US") : value.toPrecision(3);
  return `${toPersianDigits(s).replace(/,/g, "٬").replace(".", "٫")} دلار`;
}

/** CSS-variable color for a financial delta (matches the project's tokens). */
export function deltaColor(value: number): string {
  if (value > 0) return "var(--success)";
  if (value < 0) return "var(--danger)";
  return "var(--text-3)";
}

const FA_MONTHS = [
  "فروردین", "اردیبهشت", "خرداد", "تیر", "مرداد", "شهریور",
  "مهر", "آبان", "آذر", "دی", "بهمن", "اسفند",
];

const jalaliParts = new Intl.DateTimeFormat("en-US-u-ca-persian", {
  timeZone: "Asia/Tehran",
  year: "numeric",
  month: "numeric",
  day: "numeric",
});

/** Jalali date. long=true (default) → "۱ فروردین ۱۴۰۴", false → "۱۴۰۴/۰۱/۰۱". */
export function formatJalali(date: string | number | Date, long = true): string {
  const d = typeof date === "string" || typeof date === "number" ? new Date(date) : date;
  const parts = jalaliParts.formatToParts(d);
  const get = (t: string) => parts.find((p) => p.type === t)?.value ?? "";
  const y = Number(get("year"));
  const m = Number(get("month"));
  const day = Number(get("day"));
  if (long) {
    return `${toPersianDigits(day)} ${FA_MONTHS[m - 1]} ${toPersianDigits(y)}`;
  }
  const mm = String(m).padStart(2, "0");
  const dd = String(day).padStart(2, "0");
  return toPersianDigits(`${y}/${mm}/${dd}`);
}

/** Short Jalali for chart axes, e.g. "۱ فروردین". */
export function formatJalaliShort(date: string | number | Date): string {
  const d = typeof date === "string" || typeof date === "number" ? new Date(date) : date;
  const parts = jalaliParts.formatToParts(d);
  const get = (t: string) => parts.find((p) => p.type === t)?.value ?? "";
  return `${toPersianDigits(Number(get("day")))} ${FA_MONTHS[Number(get("month")) - 1]}`;
}

/* ── تفکیک‌هایی که نبودشان باگِ عددی می‌سازد ─────────────────────────────── */

/**
 * **واحدِ درصد** (percentage point) — نه درصد.
 *
 * ── چرا تابعِ جداست ──────────────────────────────────────────────────────
 * «حبابِ این صندوق ۲ واحدِ درصد از میانه بالاتر است» و «حباب ۲٪ بالاتر است»
 * دو گزارهٔ متفاوت‌اند و با هم اشتباه گرفتن‌شان عددِ خروجی را عوض می‌کند.
 * وقتی هر دو با `formatPercent` نوشته شوند، هیچ‌کس در UI نمی‌تواند تشخیص
 * بدهد کدام است. این تابع تفاوت را **در خودِ متن** می‌گذارد.
 */
export function formatPercentPoints(value: number, digits = 1): string {
  const sign = value < 0 ? "−" : "";
  const body = toPersianDigits(Math.abs(value).toFixed(digits)).replace(".", "٫");
  return `${sign}${body} واحدِ درصد`;
}

/** شمارش با ارقامِ فارسی و جداکنندهٔ هزارگان، e.g. 1234 → "۱٬۲۳۴". */
export function formatCount(value: number): string {
  return toPersianDigits(groupThousands(value));
}

/**
 * ساعتِ تهران از یک مهرِ زمانی.
 *
 * `Intl` با `timeZone: "Asia/Tehran"` استفاده می‌شود تا خروجیِ سرور (UTC) و
 * مرورگرِ کاربر (هر منطقه‌ای) یکسان باشد — وگرنه hydration ناهماهنگ می‌شود.
 */
const tehranClock = new Intl.DateTimeFormat("en-GB", {
  timeZone: "Asia/Tehran",
  hour: "2-digit",
  minute: "2-digit",
  hour12: false,
});

export function formatTehranClock(date: string | number | Date): string {
  const d = typeof date === "string" || typeof date === "number" ? new Date(date) : date;
  return toPersianDigits(tehranClock.format(d));
}

/**
 * حالتِ یک عدد در نما. **«صفرِ واقعی» و «ناموجود» یک چیز نیستند** و این نوع
 * وادار می‌کند هر مصرف‌کننده تکلیفش را روشن کند.
 */
export type ValueState = "value" | "missing";

/**
 * عددِ اختیاری → متن. `null`/`undefined`/غیرعدد → «—» (نه صفر).
 *
 * هرجا این تابع به‌کار برود، باگِ «دادهٔ ناموجود صفر نشود» دیگر ممکن نیست.
 */
export function formatOrDash(value: number | null | undefined, fmt: (n: number) => string): string {
  if (typeof value !== "number" || !isFinite(value)) return "—";
  return fmt(value);
}

/**
 * جمعِ یک ستونِ اختیاری با **پوششِ صریح**.
 *
 * ── باگی که این تابع می‌بندد ──────────────────────────────────────────────
 * الگوی `rows.reduce((s, r) => s + (r.x ?? 0), 0)` وقتی هیچ ردیفی `x` ندارد
 * عددِ `0` می‌دهد — و نما آن را «جمعِ کل: صفر» نشان می‌دهد. یعنی «نمی‌دانیم»
 * به «صفر است» ترجمه می‌شود. اینجا جمع همراهِ `covered` برمی‌گردد و اگر هیچ
 * ردیفی داده نداشت، `total` عمداً `null` است.
 */
export function sumCovered<T>(rows: readonly T[], pick: (row: T) => number | null | undefined): {
  total: number | null;
  covered: number;
  population: number;
} {
  let total = 0;
  let covered = 0;
  for (const r of rows) {
    const v = pick(r);
    if (typeof v === "number" && isFinite(v)) {
      total += v;
      covered += 1;
    }
  }
  return { total: covered > 0 ? total : null, covered, population: rows.length };
}

/**
 * ریال → تومان.
 *
 * ── چرا یک تابعِ نام‌دار، نه `/ 10` پراکنده ───────────────────────────────
 * فیدِ tsetmc ارزشِ معاملات و ارزشِ بازار را به **ریال** می‌دهد و قیمت را به
 * تومان. هر مصرف‌کننده‌ای که این را نداند عددِ ده‌برابر نشان می‌دهد — و چون
 * خروجی همچنان «معقول» به نظر می‌رسد، کسی متوجه نمی‌شود.
 *
 * شاهد (اسنپ‌شاتِ ۱۴۰۵/۰۶/۲۴): `marketValue` فملی ÷ قیمتِ تومانی ۱٫۴۳×۱۰¹³
 * سهم می‌دهد، در حالی که تعدادِ سهامِ واقعیِ فملی ۱٫۴۳×۱۰¹² است. یعنی
 * `marketValue` ریال است، نه تومان.
 */
export function rialToToman(rial: number): number {
  return rial / 10;
}

/** ارزشِ ریالیِ فید → متنِ تومانیِ خلاصه. نقطهٔ واحدِ تبدیل برای نماها. */
export function formatRialAsToman(rial: number | null | undefined): string {
  if (typeof rial !== "number" || !isFinite(rial)) return "—";
  return formatTomanShort(rialToToman(rial));
}

