}

"use client";
import React, { useState } from "react";
import { formatJalali, toPersianDigits } from "@/lib/format";
import type { ConsultationAction, RecommendationBody } from "@/lib/consultation/contracts";
import type { ReplyCommand, ReplyRead, ReplyReadOnlyReason } from "@/lib/consultation/replies";
import { questionFollowUp } from "./questionFollowUp";

/** Presentation model only. The API adapter must validate identity and parent IDs. */
export type ReplyView = { id: string; version: number; text: string; createdAt: string };
export type QuestionView = { id: string; text: string; createdAt: string; context?: string; replies: ReplyView[] };
export type ReplyEdit = { questionId: string; baseVersion: number; text: string };

export function ReplyQuestion({ question, canReply, locked, onSave, onDirty, onCancel }: {
  question: QuestionView; canReply: boolean; locked: boolean;
  onSave?: (edit: ReplyEdit) => Promise<boolean>; onDirty?: () => void; onCancel?: () => void;
}) {
  const versions = [...question.replies].sort((a, b) => b.version - a.version);
  const latest = versions[0];
  const [draft, setDraft] = useState<ReplyEdit | null>(null);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const disabled = locked || saving || Boolean(error);
  return <article className="min-w-0 space-y-3 rounded-lg border border-line p-3">
    <p className="text-sm font-bold">پرسش عضو · <time dateTime={question.createdAt}>{formatJalali(question.createdAt)}</time></p>
    {question.context && <p className="break-words text-sm">{question.context}</p>}
    <p className="whitespace-pre-wrap break-words text-sm leading-7">{question.text}</p>
    {latest ? <div className="space-y-2 border-s-2 border-line ps-3"><p className="text-sm font-bold">پاسخ مشاور · نسخهٔ {toPersianDigits(latest.version)} · <time dateTime={latest.createdAt}>{formatJalali(latest.createdAt)}</time></p><p className="whitespace-pre-wrap break-words text-sm leading-7">{latest.text}</p></div> : <p className="text-sm">هنوز پاسخی ثبت نشده است.</p>}
    {versions.length > 1 && <details className="text-sm"><summary className="cursor-pointer">نسخه‌های قبلی پاسخ</summary><ul className="mt-3 space-y-3">{versions.slice(1).map(reply => <li key={reply.id}><p>نسخهٔ {toPersianDigits(reply.version)} · <time dateTime={reply.createdAt}>{formatJalali(reply.createdAt)}</time></p><p className="whitespace-pre-wrap break-words leading-7">{reply.text}</p></li>)}</ul></details>}
    {error && <p role="alert" className="text-sm leading-7">{error}</p>}
    {canReply && onSave && !draft && <button type="button" className="btn btn-outline !whitespace-normal max-w-full min-w-0 break-words" disabled={disabled} onClick={() => { setDraft({ questionId: question.id, baseVersion: latest?.version ?? 0, text: latest?.text ?? "" }); onDirty?.(); }}>{latest ? "اصلاح پاسخ در نسخهٔ تازه" : "نوشتن پاسخ"}</button>}
    {canReply && onSave && draft && <form onSubmit={async event => {
      event.preventDefault();
      if (disabled || !draft.text.trim() || (latest?.version ?? 0) !== draft.baseVersion) return;
      setSaving(true);
      try { if (await onSave({ ...draft, text: draft.text.trim() })) setDraft(null); }
      catch { setError("نتیجهٔ انتشار مشخص نشد. متن حفظ شده است؛ پیش از تلاش تازه، وضعیت ثبت را بررسی کنید."); }
      finally { setSaving(false); }
    }}><fieldset disabled={disabled} className="space-y-3"><legend className="sr-only">پاسخ به همین پرسش</legend>
      <label className="block space-y-2 text-sm"><span>متن پاسخ مشاور</span><textarea className="input min-h-28 w-full min-w-0" value={draft.text} maxLength={2000} onChange={event => { setDraft({ ...draft, text: event.target.value }); onDirty?.(); }} /></label>
      {(latest?.version ?? 0) !== draft.baseVersion && <p role="alert" className="text-sm">از زمان شروع ویرایش، پاسخ تازه‌ای ثبت شده است. متن شما حفظ شده؛ پیش از انتشار، نسخهٔ تازه را بررسی کنید.</p>}
      <p className="text-xs leading-6">با انتشار، این پاسخ در دسترس عضو قرار می‌گیرد. اگر جمع‌بندی تغییر می‌کند، برای آن نسخهٔ تازه بسازید و مسیر تأیید را طی کنید.</p>
      <details className="text-sm"><summary className="cursor-pointer">پیش‌نمایش پاسخ برای عضو</summary><p className="whitespace-pre-wrap break-words leading-7">{draft.text.trim() || "هنوز متنی ننوشته‌اید."}</p></details>
      <div className="flex flex-wrap gap-3"><button type="submit" className="btn btn-gold !whitespace-normal max-w-full min-w-0 break-words" disabled={!draft.text.trim() || (latest?.version ?? 0) !== draft.baseVersion}>انتشار {draft.baseVersion ? "نسخهٔ تازهٔ پاسخ" : "پاسخ"} برای عضو</button><button type="button" className="btn btn-outline !whitespace-normal max-w-full min-w-0 break-words" onClick={() => { setDraft(null); onCancel?.(); }}>انصراف از ویرایش پاسخ</button></div>
    </fieldset></form>}
  </article>;
}

const readOnlyLabels: Record<ReplyReadOnlyReason, string> = {
  not_owner: "پاسخ‌گویی توسط آرش انجام می‌شود.", revoked: "دسترسی مشاور لغو شده؛ تاریخچه برای عضو محفوظ است.",
  unpublished: "این نسخه هنوز برای عضو منتشر نشده است.", withdrawn: "این نسخه پس گرفته شده؛ پاسخ تازه روی آن منتشر نمی‌شود.",
  superseded: "نسخهٔ تازه‌تری وجود دارد؛ ابتدا آن نسخه را بررسی کنید.", expired: "موعد بازبینی رسیده؛ ابتدا جمع‌بندی را بازبینی کنید.",
  basis_changed: "اطلاعات مالی مبنا تغییر کرده؛ ابتدا جمع‌بندی را بازبینی کنید.", research_changed: "پژوهش مبنا تغییر کرده؛ ابتدا جمع‌بندی را بازبینی کنید.",
};
export function SessionReplies({ data, feedback, sessionVersion, sessionActions = [], advisor, locked, onCommand, onDirty, onCancel }: {
  data: ReplyRead; feedback: ConsultationAction[]; sessionVersion: number; advisor: boolean; locked: boolean;
  sessionActions?: RecommendationBody["actions"];
  onCommand?: (command: ReplyCommand) => Promise<boolean>; onDirty: () => void; onCancel?: () => void;
}) {
  const questions = questionFollowUp(data, feedback, sessionActions);
  if (!questions) return <p role="alert">پاسخ با پرسش‌های این نسخه تطبیق ندارد؛ پرونده را دوباره بخوانید.</p>;
  return <div className="space-y-3">{advisor && data.readOnlyReason && <p role="status" className="text-sm leading-7">{readOnlyLabels[data.readOnlyReason]}</p>}<RepliesPanel sessionId={data.sessionId} sessionVersion={sessionVersion} questions={questions} canReply={advisor && data.canReply} locked={locked} onDirty={onDirty} onCancel={onCancel} onSave={onCommand ? edit => onCommand({ kind: "publish_reply", relationshipId: data.relationshipId, sessionId: data.sessionId, ...edit, purpose: "clarification" }) : undefined} /></div>;
}

export default function RepliesPanel({ sessionId, sessionVersion, questions, canReply, locked, onSave, onDirty, onCancel }: {
  sessionId: string; sessionVersion: number; questions: QuestionView[]; canReply: boolean; locked: boolean;
  onSave?: (edit: ReplyEdit) => Promise<boolean>; onDirty?: () => void; onCancel?: () => void;
}) {
  const [editingQuestion, setEditingQuestion] = useState<string | null>(null);
  const [filter, setFilter] = useState<"all" | "waiting" | "answered">("all");
  const waiting = questions.filter(question => question.replies.length === 0).length;
  const visible = questions.filter(question => filter === "all" || (filter === "waiting" ? question.replies.length === 0 : question.replies.length > 0));
  return <section className="min-w-0 space-y-3" aria-label={`پرسش و پاسخ نسخهٔ ${toPersianDigits(sessionVersion)}`}>
    <h4 className="font-bold">پرسش و پاسخ همین نسخه</h4>
    {questions.length > 0 && <><p className="text-sm">{toPersianDigits(waiting)} پرسش بدون پاسخ ثبت‌شده · {toPersianDigits(questions.length - waiting)} پرسش دارای پاسخ ثبت‌شده</p><label className="block space-y-2 text-sm"><span>نمایش پرسش‌ها</span><select className="input w-full sm:w-auto" value={filter} disabled={locked || editingQuestion !== null} onChange={event => setFilter(event.target.value as typeof filter)}><option value="all">همهٔ پرسش‌ها</option><option value="waiting">بدون پاسخ ثبت‌شده</option><option value="answered">دارای پاسخ ثبت‌شده</option></select></label></>}
    {questions.length === 0 ? <p className="text-sm">پرسشی برای این نسخه ثبت نشده است.</p> : visible.length === 0 ? <p className="text-sm">پرسشی مطابق این فیلتر نیست.</p> : visible.map(question => <ReplyQuestion key={`${sessionId}:${question.id}`} question={question} canReply={canReply} locked={locked || (editingQuestion !== null && editingQuestion !== question.id)} onSave={onSave} onDirty={() => { setEditingQuestion(question.id); onDirty?.(); }} onCancel={() => { setEditingQuestion(null); onCancel?.(); }} />)}
  </section>;
}

import type { ConsultationAction, RecommendationBody } from "@/lib/consultation/contracts";
import type { ReplyRead } from "@/lib/consultation/replies";

/** Projection of an already validated read, never a ticket lifecycle or a permission. */
export function questionFollowUp(data: ReplyRead, feedback: ConsultationAction[], actions: RecommendationBody["actions"]) {
  const questions = feedback.filter(item => item.sessionId === data.sessionId && item.status === "question");
  const ids = new Set(questions.map(item => item.id));
  if (data.replies.some(reply => reply.sessionId !== data.sessionId || !ids.has(reply.questionId))) return null;
  return questions.map(question => ({
    id: question.id,
    text: question.text ?? "متن پرسش در دسترس نیست",
    createdAt: question.createdAt,
    context: question.actionKey === null ? "دربارهٔ همین جمع‌بندی" : `اقدام مرتبط: ${actions.find(action => action.actionKey === question.actionKey)?.title ?? "عنوان اقدام در این نسخه در دسترس نیست"}`,
    replies: data.replies.filter(reply => reply.questionId === question.id),
  }));
}

"use client";
import React, { useRef, useState } from "react";
import Field from "./Field";

export interface ActionFeedbackEdit { status: "partial" | "not_done"; text: string; baseVersion: number }
export default function ActionFeedback({ baseVersion, locked, onSave, onBegin, onCancel, writeEnabled = false }: {
  baseVersion: number; locked: boolean; onSave: (edit: ActionFeedbackEdit) => Promise<boolean>; onBegin: () => void; onCancel: () => void;
  writeEnabled?: boolean;
}) {
  const [edit, setEdit] = useState<ActionFeedbackEdit | null>(null), [error, setError] = useState(""), [saving, setSaving] = useState(false);
  const busy = useRef(false);
  const stale = Boolean(edit && edit.baseVersion !== baseVersion);
  const begin = (status: ActionFeedbackEdit["status"]) => { if (!writeEnabled || locked || busy.current || edit) return; setEdit({ status, text: "", baseVersion }); setError(""); onBegin(); };
  const save = async () => {
    if (!edit || !writeEnabled || locked || stale || busy.current) return;
    if (!edit.text.trim()) { setError("جزئیات این وضعیت را بنویسید؛ چیزی ثبت نشده است."); return; }
    busy.current = true; setSaving(true); setError("");
    try { if (await onSave({ ...edit, text: edit.text.trim() })) { setEdit(null); onCancel(); } }
    catch { setError("ثبت پیگیری تأیید نشد؛ متن شما حفظ شده است."); }
    finally { busy.current = false; setSaving(false); }
  };
  return <div className="min-w-0 space-y-3">
    <div className="flex flex-wrap gap-2"><button type="button" className="btn btn-outline !whitespace-normal max-w-full min-w-0 break-words" disabled={!writeEnabled || locked || Boolean(edit) || saving} onClick={() => begin("partial")}>بخشی انجام دادم</button><button type="button" className="btn btn-outline !whitespace-normal max-w-full min-w-0 break-words" disabled={!writeEnabled || locked || Boolean(edit) || saving} onClick={() => begin("not_done")}>انجام ندادم</button></div>
    {edit && <form aria-label="جزئیات پیگیری اقدام" className="min-w-0 space-y-3" onSubmit={event => { event.preventDefault(); void save(); }}>
      <p className="text-sm">وضعیت انتخاب‌شده: {edit.status === "partial" ? "بخشی انجام دادم" : "انجام ندادم"}. این ثبت، موجودی مالی شما را تغییر نمی‌دهد.</p>
      {stale && <p role="alert">پیگیری تازه‌تری برای این اقدام خوانده شد؛ متن شما حفظ شده است. برای استفاده از نسخه تازه، این پیش‌نویس را لغو و دوباره باز کنید.</p>}
      {!writeEnabled && <p role="alert">ثبت این وضعیت اکنون فعال نیست؛ متن شما حفظ شده است.</p>}
      {error && <p role="alert">{error}</p>}
      <fieldset disabled={locked || saving || stale} className="min-w-0 space-y-3"><legend className="sr-only">شرح نتیجه اقدام</legend><Field label="چه بخشی انجام شد یا چرا انجام نشد؟" value={edit.text} onChange={text => setEdit({ ...edit, text })} multiline maxLength={2000} /><button type="submit" disabled={!writeEnabled} className="btn btn-gold !whitespace-normal max-w-full min-w-0 break-words">{saving ? "در حال ثبت همان پیگیری…" : "ثبت همین وضعیت اقدام"}</button></fieldset>
      <button type="button" disabled={locked || saving} className="btn btn-outline !whitespace-normal max-w-full min-w-0 break-words" onClick={() => { if (!busy.current) { setEdit(null); setError(""); onCancel(); } }}>لغو این پیش‌نویس پیگیری</button>
    </form>}
  </div>;
}

import { cashFlowObject as object, cashFlowText as text, cashFlowUuid as uuid, cashFlowDay as day, validateCashFlowPeriod, validateCashFlowPayload, type CashFlowPayload } from "../portfolio/cashFlowApiContract";
import { validateGoalsPayload, type GoalsPayload } from "../portfolio/goalsApiContract";
export const CONSULTATION_BODY_LIMIT = 150_000;
export interface FinancialBasis { holdingsVersionId: string | null; cashFlowPeriod: { startOn: string; endOn: string }; cashFlowVersionId: string | null; goalsVersionId: string | null }
export interface RecommendationBody {
 topic: string; goal: string; clientSummary: string; rationale: string; limitations: string; reviewOn: string;
 basis: FinancialBasis; researchVersionIds: string[];
 evidence: { label: string; url: string | null; asOf: string }[];
 actions: { actionKey: string; title: string; dueOn: string; responsible: "member" | "advisor" }[];
}
export const FEEDBACK_STATUSES = ["viewed", "acknowledged", "doing", "done", "question", "partial", "not_done"] as const;
export type FeedbackStatus = typeof FEEDBACK_STATUSES[number];
export const isFeedbackStatus = (value: unknown): value is FeedbackStatus => typeof value === "string" && FEEDBACK_STATUSES.some(status => status === value);
export const actionFeedback = (status: FeedbackStatus) => status === "doing" || status === "done" || status === "partial" || status === "not_done";
export const feedbackNeedsDetails = (status: FeedbackStatus) => status === "partial" || status === "not_done";
export type ConsultationCommand =
 | { kind: "grant"; advisorId: string; clientLabel: string }
 | { kind: "revoke"; relationshipId: string }
 | { kind: "save"; relationshipId: string; sessionKey: string; baseVersion: number; body: RecommendationBody; privateNote: string | null }
 | { kind: "submit" | "approve" | "publish" | "withdraw"; relationshipId: string; sessionId: string; contentHash: string; note: string | null }
 | { kind: "feedback"; relationshipId: string; sessionId: string; actionKey: string | null; baseVersion: number; status: FeedbackStatus; text: string | null };
export interface ConsultationRequest { contractVersion: "consultation-request.v1"; expectedActorId: string; clientToken: string; command: ConsultationCommand }
export interface ConsultationReceipt { contractVersion: "consultation-write.v1"; actorId: string; clientToken: string; command: ConsultationCommand; id: string; version: number; reused: boolean; canonicalContentHash: string }
export interface Relationship { id: string; clientId: string; advisorId: string; clientLabel: string; createdAt: string; revoked: boolean }
export interface ConsultationSession { id: string; relationshipId: string; sessionKey: string; version: number; createdAt: string; actorId: string; contentHash: string; body: RecommendationBody; approval: { actorId: string; createdAt: string } | null; state: "draft" | "submitted" | "approved" | "published" | "withdrawn" }
export interface ConsultationEvent { id: string; sessionId: string; kind: "submit" | "approve" | "publish" | "withdraw"; actorId: string; createdAt: string; note: string | null }
export interface ConsultationAction { id: string; sessionId: string; actionKey: string | null; version: number; status: FeedbackStatus; text: string | null; actorId: string; createdAt: string }
export interface ConsultationDossier {
 basis: FinancialBasis;
 holdings: null | { id: string; version: number; positions: { key: string; title: string; quantity: string | null; unit: string; ownershipPercent: string; declaredValueToman: number | null; source: string | null; asOf: string | null }[]; debts: { key: string; title: string; balanceToman: number; balanceAsOf: string; nextInstallmentToman: number | null; nextDueOn: string | null }[] };
 cashFlow: null | { id: string; version: number; payload: CashFlowPayload };
 goals: null | { id: string; version: number; payload: GoalsPayload };
}
export interface ConsultationRead {
 contractVersion: "consultation-read.v1";
 capabilities?: { extendedFeedbackWrite: boolean };
 actor: { id: string; isAdvisor: boolean; isOwner: boolean };
 advisors: { id: string; displayName: string; isOwner: boolean }[];
 relationships: Relationship[]; selected: Relationship | null; dossier: ConsultationDossier | null;
 sessions: ConsultationSession[]; notes: { sessionId: string; note: string | null }[]; events: ConsultationEvent[]; actions: ConsultationAction[];
}
const id = (v: unknown): string => { if (!uuid(v)) throw Error("شناسه معتبر نیست."); return v.toLowerCase(); };
const nullableId = (v: unknown) => v === null ? null : id(v);
const nullableText = (v: unknown, max: number) => v === null ? null : text(v, max);
const version = (v: unknown, zero = false): number => { if (typeof v !== "number" || !Number.isInteger(v) || v < (zero ? 0 : 1) || v > (zero ? 2_147_483_646 : 2_147_483_647)) throw Error("نسخه معتبر نیست."); return v; };
const hash = (v: unknown): string => { if (typeof v !== "string" || !/^[a-f0-9]{64}$/.test(v)) throw Error("اثر انگشت معتبر نیست."); return v; };
const list = (v: unknown, max: number): unknown[] => { if (!Array.isArray(v) || v.length > max) throw Error("تعداد رکوردها معتبر نیست."); return v; };
const unique = (values: string[]) => { if (new Set(values).size !== values.length) throw Error("شناسه تکراری است."); };
function evidenceUrl(v: unknown): string | null {
 if (v === null) return null;
 const value = text(v, 1000);
 if (!/^https?:\/\/([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)*[a-z]([a-z0-9-]*[a-z0-9])?(\/.*)?$/i.test(value) || /[\\\x00-\x20\x7f-\uffff]/.test(value) || /(^|\.)xn--/.test(value.toLowerCase().split("://")[1].split("/")[0])) throw Error("نشانی HTTP منبع بدون نام کاربری و رمز لازم است.");
 return value;
}
export function validateFinancialBasis(value: unknown): FinancialBasis {
 const b = object(value, ["holdingsVersionId", "cashFlowPeriod", "cashFlowVersionId", "goalsVersionId"]);
 return { holdingsVersionId: nullableId(b.holdingsVersionId), cashFlowPeriod: validateCashFlowPeriod(b.cashFlowPeriod), cashFlowVersionId: nullableId(b.cashFlowVersionId), goalsVersionId: nullableId(b.goalsVersionId) };
}
