// Test-only composition phase. Called by the existing real browser case after
// its real advisor response/member followup, in the SAME owned ctx and relation.
// No runner, lifecycle, SQL, provider, endpoint fixture or automatic retry.
import { randomUUID } from 'node:crypto';
import { resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { sdkCookies, storageAudit, browserDestination } from './browser.mjs';
