const root=fileURLToPath(new URL('../../../',import.meta.url));
const load=async path=>{const m=await import(pathToFileURL(resolve(root,path)));return m.default??m;};
const check=(v,code)=>{if(!v)throw Error('p03_composition_'+code);};
const period={startOn:'2026-10-01',endOn:'2026-10-31'};

// Root must supply this attestation from its independently verified owned
// lifecycle. Missing evidence stops BEFORE any composition operation.
export function bindCompositionContext(ctx){
 const b=ctx.compositionBinding;
 check(b?.schema==='p03-composition-binding.v1'&&b.appSha===app.sha&&b.appTree===app.tree
   &&b.tmpfsVerified===true&&b.runId===ctx.id&&ctx.origin===origin
   &&b.authCreatedIds?.length===4&&new Set(b.authCreatedIds).size===4
   &&Object.values(ctx.users).every(u=>b.authCreatedIds.includes(u.id))
   &&b.initialPasswordLogins===4&&b.productServiceRight==='NOT_CONNECTED'&&b.serverWritesReleased===true,'root_binding_required');
 let authPasswords=b.initialPasswordLogins,authLogouts=0,negativeRpc=0,ordinal=0;
 const admission=createProductAdmission(Object.fromEntries(Object.entries(ctx.users).map(([a,u])=>[a,u.id])),row=>ctx.write('composition-'+row.kind+'-'+String(row.ordinal).padStart(3,'0')+'.json',row,true));
 const forwardBrowser=createBrowserForwardGate(admission,browserDestination);
 const forwardReadOnlyNav=createBrowserForwardGate(admission,assembledBrowserDestination,true);
 const forwardReadOnlySummary=createBrowserForwardGate(admission,(url,method)=>browserDestination(url,method,'feedback-reader-v1'),true);
 const wrapped={...ctx,
  forwardReadOnlyNav,forwardReadOnlySummary,
  async api(actor,path,body){
   check(!admission.snapshot().stopped,'shared_admission_stopped');
   if(body!==undefined)admission.admit(actor,origin+path,JSON.stringify(body));
   try{const result=await ctx.api(actor,path,body);if(body!==undefined)admission.record(actor,origin+path,JSON.stringify(body),result.status);return result;}catch(error){admission.stopUnknown();throw error;}
  },
  async newSession(actor){check(authPasswords<9,'password_cap');authPasswords++;return ctx.newSession(actor);},
  async post(path,body,headers){
   if(path==='/rest/v1/rpc/lookup_consultation_ticket_attempt'){
    check(negativeRpc===0&&headers?.Authorization==='Bearer '+ctx.users.b.session.token&&headers?.apikey===ctx.anon,'negative_rpc_binding');negativeRpc++;
